INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'frFR', 'Témérité fatidique : sépulcre des Fondateurs', '', '', '', '', '', '', '', '', 45114),
(66694, 'frFR', 'Témérité fatidique : sanctum de Domination', '', '', '', '', '', '', '', '', 45114),
(66661, 'frFR', 'Monnaie au long cours', 'Renseignez-vous auprès d\’un négociant d\’Oribos.', '<Ce curieux objet soulève plus de questions qu\’il n\’offre de réponses. Comment est-il entré en votre possession ? À quoi sert-il ? Est-il dangereux ?>\n\n<Si la cité d\’éternité ne peut pas vous apporter de réponses, les négociants du secteur s\’en chargeront.>', '', '', '', '', '', '', 45114),
(66649, 'frFR', 'La roue tourne', 'Terrassez $1oa boss de raid fatidique différents.', '<Votre pouvoir intérieur croît à mesure que vous surmontez les épreuves. Quelle que soit l\’origine de ces anomalies, elles sont à présent source de réconfort, et non plus de confusion.>\n\n<Plongez à nouveau dans l\’incertitude, luttez contre les ténèbres et saisissez la fatalité à pleine main.>', '', '', '', '', '', '', 45114),
(66648, 'frFR', 'Fatalité contrariée', 'Terrassez 30 boss de raid fatidique différents.', '<La réalité se met à tournoyer autour de vous. Vos souvenirs de cet endroit se brouillent et se transforment du tout au tout à chaque instant qui passe. Quelque chose a changé.>\n\n<Vous avez l\’intime conviction que, malgré ces troublantes ressemblances, ce n\’est pas l\’endroit que vous avez connu autrefois. Pas exactement, en tout cas.>\n\n<Quoi qu\’il en soit, le chemin qui s\’ouvre à vous vous attire irrésistiblement. Aucun subterfuge ou autre distorsion ne vous détournera de votre destinée.>', '', '', '', '', '', '', 45114),
(66619, 'frFR', 'Antros', '', '', '', '', '', '', '', '', 45114),
(66618, 'frFR', 'Mor\’geth', '', '', '', '', '', '', '', '', 45114),
(65412, 'frFR', 'Énigmatique imbroglio', '', '', '', '', '', '', '', '', 45114),
(65411, 'frFR', 'Une situation énigmatique', '', '', '', '', '', '', '', '', 45114),
(54603, 'frFR', 'Surveillant Krix', '', '', '', '', '', '', '', '', 45114),
(54391, 'frFR', 'Donations pour Sombrivage : béryl jaune rapide', 'Apportez $1oa Filets assaisonnés à Sénédras, au Port de Boralus.', 'Ah, rien de tel qu\’une belle pièce de viande pour restaurer nos alliés avant de les expédier sur les lignes de front. Sans compter qu\’on peut en faire un délicieux ragoût, un mets dont nos troupes raffolent lorsque le vent se lève et que le froid les saisit au cœur de la nuit.\n\nApportez-moi des filets assaisonnés, que je remette aux bons soins de nos officiers de ravitaillement.', '', '', '', '', '', '', 45114),
(54381, 'frFR', 'Donations pour Sombrivage : encre bleu outremer', 'Apportez $1oa Poissons-chats grillés à Sénédras, au Port de Boralus.', 'Salutations, $gvoyageur:voyageuse;.\n\nOn m\’a confié la gestion de nos vivres et le fait est que nous manquons cruellement de poisson, ces temps-ci. Auriez-vous quelque surplus à consacrer à l\’effort de guerre ?', '', '', '', '', '', '', 45114),
(53317, 'frFR', 'Foudrargent dense', '', '', '', '', '', '', '', '', 45114),
(49053, 'frFR', 'Guetteur', '', '', '', '', '', '', '', '', 45114),
(41695, 'frFR', 'DANGER : Profania', '', '', '', '', '', '', '', '', 45114),
(31756, 'frFR', 'Fortes chances de pluie', 'Détruisez les Bâtons des Mande-foudre.', 'Les mogu sont en train d\’invoquer une sorte d\’orage inquiétant sur l\’escalier Doré. En général, les mogu et la foudre ne sont pas une association très agréable. Mon avis est qu\’il faudrait les arrêter.$b$bVous devriez pouvoir trouver leurs bâtons mande-foudre assez facilement, vu les éclairs géants qui en sortent. Ça ne vous dérangerait pas de les renverser ou les détruire pour moi ? Ça m\’aiderait à mieux dormir.', '', '', '', '', '', '', 45114),
(31528, 'frFR', 'Un défi de taille : le sombre maître Gandling', 'Terminez la Scholomance en mode Défi.', '$n, il faut que vous rassembliez un groupe intrépide et que vous vous rendiez dans les profondeurs de la Scholomance. Une fois là-bas, activez l\’orbe de défi et débarrassez les lieux de la présence maléfique du Sombre Maître Gandling.$B$BRevenez me voir quand vous aurez réussi ce défi, et je vous récompenserai généreusement.', '', '', '', '', '', '', 45114),
(6847, 'frFR', 'L\'Œil-qui-voit-tout de Maître Ryson', 'Récupérer l\’Oeil qui-voit-tout de Maître Ryson dans les Grottes Haches-d\’hiver, puis le rapporter à Maître Ryson.$B$BSachez que l\’on dit de l\’Oeil qui-voit-tout de Maître Ryson qu\’il contient une terrible malédiction !', 'Votre guerre dans le cœur d\’Alterac ne signifie rien pour le Syndicat, $c. Nous ferons comme nous avons toujours fait : attendre jusqu\’à ce qu\’une opportunité claire de victoire émerge des cendres et des décombres, puis frapper.$B$BCe n\’est pas pour cela, cependant, que nous sommes là aujourd\’hui. L\’Œil-qui-voit-tout a été volé par les Trolls Haches-d\’hiver de la région.$B$BRécupérez l\’Œil et nous nous mettrons à votre service.$B$BRevenez me voir, une fois que l\’Œil est en votre possession, et puis je réfléchirai à la question.$B$B<Maître Ryson sourit.>', 'Oeil qui-voit-tout de Maître Ryson retrouvé', '', '', '', '', 'Retournez voir le Maître du Syndicat Ryson dans la Vallée d\'Alterac.', 45114);

